1	// Cliente HTTP para PagBank API v4 — sandbox e produção
2	export class PagBankClient {
3	  private readonly baseUrl: string;
4	  private readonly token: string;
5	
6	  constructor(token: string, sandbox: boolean) {
7	    this.token = token.trim();
8	    this.baseUrl = sandbox
9	      ? 'https://sandbox.api.pagseguro.com'
10	      : 'https://api.pagseguro.com';
11	  }
12	
13	  private headers() {
14	    return {
15	      'Content-Type': 'application/json',
16	      'Authorization': `Bearer ${this.token}`,
17	      'Accept': 'application/json',
18	      'x-api-version': '4.0',
19	    };
20	  }
21	
22	  private async request<T>(method: string, path: string, body?: unknown): Promise<T> {
23	    const res = await fetch(`${this.baseUrl}${path}`, {
24	      method,
25	      headers: this.headers(),
26	      body: body ? JSON.stringify(body) : undefined,
27	    });
28	
29	    const json = await res.json() as any;
30	
31	    if (!res.ok) {
32	      const msg = json?.error_messages?.[0]?.description ?? json?.message ?? `HTTP ${res.status}`;
33	      throw new Error(`PagBank: ${msg}`);
34	    }
35	
36	    return json as T;
37	  }
38	
39	  // Cria ordem PIX — retorna qr_code e link
40	  // splits (opcional): distribui o valor entre vendedor e plataforma automaticamente
41	  async criarOrdemPix(params: {
42	    reference_id: string;
43	    valor_centavos: number;
44	    customer: { name: string; email: string; tax_id: string };
45	    itens: { name: string; quantity: number; unit_amount: number }[];
46	    webhook_url: string;
47	    splits?: Array<{
48	      method: 'FIXED' | 'PERCENTAGE';
49	      receivers: Array<{ account: { id: string }; amount: { value: number } }>;
50	    }>;
51	  }) {
52	    const expiracao = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
