8	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
9	
10	const AdminNav = ({ active }) => {
11	  const navigate = useNavigate();
12	  const { signOut } = useAuth();
13	  const links = [
14	    { label: 'Dashboard', path: '/admin' },
15	    { label: 'Empresas', path: '/admin/empresas' },
16	    { label: 'Categorias', path: '/admin/categorias' },
17	    { label: 'Tipos',      path: '/admin/tipos-estabelecimento' },
18	    { label: 'Tags',       path: '/admin/tags' },
19	    { label: 'Comissões', path: '/admin/comissoes' },
20	    { label: 'Configurações', path: '/admin/configuracoes' },
21	  ];
22	  return (
23	    <nav className="flex gap-3 items-center">
24	      {links.map((l) => (
25	        <button
26	          key={l.path}
27	          onClick={() => navigate(l.path)}
28	          className={`px-4 py-2 text-sm font-medium rounded-lg ${
29	            active === l.path ? 'text-white bg-blue-600' : 'text-gray-700 dark:text-zinc-300 hover:bg-gray-100 dark:hover:bg-zinc-800'
30	          }`}
31	        >
32	          {l.label}
33	        </button>
34	      ))}
35	      <button
36	        onClick={async () => { await signOut(); navigate('/customer-registration-login'); }}
37	        className="px-4 py-2 text-sm font-medium text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/40 rounded-lg border border-red-200 dark:border-red-900"
38	      >
39	        Sair
40	      </button>
41	      <ThemeToggle inline />
42	    </nav>
43	  );
44	};
45	
46	const Modal = ({ empresa, onClose, onSave }) => {
47	  const [form, setForm] = useState({
48	    name: empresa?.name ?? '',
49	    address: empresa?.address ?? '',
50	    comissao_pct: empresa?.comissao_pct ?? 5,
51	    user_id: empresa?.user_id ?? '',
52	    modulo_delivery: empresa?.modulo_delivery ?? true,
53	    modulo_salao: empresa?.modulo_salao ?? false,
54	  });
55	  const [salvando, setSalvando] = useState(false);
56	
57	  const handleSubmit = async (e) => {
58	    e.preventDefault();
59	    setSalvando(true);
60	    try {
61	      if (empresa) {
62	        await atualizarEmpresa(empresa.id, form);
63	      } else {
64	        await criarEmpresa(form);
65	      }
66	      onSave();
67	    } catch (err) {
68	      alert(err.message);
69	    } finally {
70	      setSalvando(false);
71	    }
72	  };
73	
74	  return (
75	    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
76	      <div className="bg-white dark:bg-zinc-800 rounded-xl w-full max-w-md p-6">
77	        <h3 className="text-lg font-semibold mb-4 text-gray-900 dark:text-zinc-100">{empresa ? 'Editar Empresa' : 'Nova Empresa'}</h3>
78	        <form onSubmit={handleSubmit} className="space-y-4">
79	          <div>
80	            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">Nome *</label>
81	            <input
82	              required
83	              className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
84	              value={form.name}
85	              onChange={(e) => setForm({ ...form, name: e.target.value })}
86	            />
87	          </div>
88	          <div>
89	            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">Endereço</label>
90	            <input
91	              className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
92	              value={form.address}
93	              onChange={(e) => setForm({ ...form, address: e.target.value })}
94	            />
95	          </div>
96	          <div>
97	            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">Comissão plataforma (%)</label>
98	            <input
99	              type="number"
100	              min="0"
101	              max="100"
102	              step="0.5"
103	              className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
104	              value={form.comissao_pct}
105	              onChange={(e) => setForm({ ...form, comissao_pct: parseFloat(e.target.value) })}
106	            />
107	          </div>
108	          <div>
109	            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">
110	              UUID do dono (restaurant_owner)
111	            </label>
112	            <input
113	              className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-blue-500 font-mono text-xs"
114	              placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"
115	              value={form.user_id}
116	              onChange={(e) => setForm({ ...form, user_id: e.target.value.trim() })}
117	            />
118	            <p className="text-xs text-gray-400 dark:text-zinc-500 mt-1">
119	              UUID do usuário cadastrado como restaurant_owner. Deixe vazio se não houver dono ainda.
120	            </p>
121	          </div>
122	          <div>
123	            <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-2">Módulos liberados</label>
124	            <div className="flex flex-col gap-2">
125	              <label className="flex items-center gap-2 text-sm text-gray-700 dark:text-zinc-300">
126	                <input
127	                  type="checkbox"
128	                  checked={form.modulo_delivery}
129	                  onChange={(e) => setForm({ ...form, modulo_delivery: e.target.checked })}
130	                />
131	                Delivery
132	              </label>
133	              <label className="flex items-center gap-2 text-sm text-gray-700 dark:text-zinc-300">
134	                <input
135	                  type="checkbox"
136	                  checked={form.modulo_salao}
137	                  onChange={(e) => setForm({ ...form, modulo_salao: e.target.checked })}
138	                />
139	                Salão (mesas/comandas/garçons)
140	              </label>
141	            </div>
142	          </div>
143	          <div className="flex gap-3 pt-2">
144	            <button
145	              type="button"
146	              onClick={onClose}
147	              className="flex-1 px-4 py-2 border border-gray-300 dark:border-zinc-700 rounded-lg text-sm font-medium text-gray-700 dark:text-zinc-300 hover:bg-gray-50 dark:hover:bg-zinc-700"
148	            >
149	              Cancelar
150	            </button>
151	            <button
152	              type="submit"
153	              disabled={salvando}
154	              className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 disabled:opacity-50"
155	            >
156	              {salvando ? 'Salvando...' : 'Salvar'}
157	            </button>
158	          </div>
159	        </form>
160	      </div>
161	    </div>
162	  );
163	};
164	
165	const AdminEmpresas = () => {
166	  const navigate = useNavigate();
167	  const { isLocalMode, localRestaurantId } = useLocalMode() ?? {};
168	  const [empresas, setEmpresas] = useState([]);
169	  const [loading, setLoading] = useState(true);
170	  const [erro, setErro] = useState(null);
171	  const [modal, setModal] = useState(null); // null | 'novo' | empresa_obj
172	
173	  const carregar = async () => {
174	    setLoading(true);
175	    try {
176	      const data = await getEmpresas();
177	      let lista = data.empresas ?? [];
178	      // Modo local: restringe a 1 restaurante
179	      if (isLocalMode && localRestaurantId) {
180	        lista = lista.filter((e) => e.id === localRestaurantId);
181	      }
182	      setEmpresas(lista);
183	    } catch (e) {
184	      setErro(e.message);
185	    } finally {
186	      setLoading(false);
187	    }
188	  };
189	
190	  useEffect(() => { carregar(); }, []);
191	
192	  const handleRemover = async (empresa) => {
193	    if (!confirm(`Remover "${empresa.name}"? Esta ação não pode ser desfeita.`)) return;
194	    try {
195	      await removerEmpresa(empresa.id);
196	      carregar();
197	    } catch (e) {
198	      alert(e.message);
199	    }
200	  };
201	
202	  const handleBloquear = async (empresa) => {
203	    const acao = empresa.bloqueado ? 'desbloquear' : 'bloquear';
204	    if (!confirm(`${acao.charAt(0).toUpperCase() + acao.slice(1)} "${empresa.name}"?`)) return;
205	    try {
206	      await bloquearEmpresa(empresa.id, !empresa.bloqueado);
207	      carregar();
208	    } catch (e) {
209	      alert(e.message);
210	    }
211	  };
212	
213	  const handleAtenderDominio = async (empresa) => {
214	    if (!confirm(`Aprovar domínio "${empresa.custom_domain}" de "${empresa.name}"? Só confirme depois de adicionar o domínio no painel do EasyPanel.`)) return;
215	    try {
216	      await atenderSolicitacaoDominio(empresa.id);
217	      carregar();
218	    } catch (e) {
219	      alert(e.message);
220	    }
221	  };
222	
223	  const handleRecusarDominio = async (empresa) => {
224	    const motivo = prompt(`Motivo da recusa do domínio "${empresa.custom_domain}" (${empresa.name}):`);
225	    if (motivo === null) return;
226	    try {
227	      await recusarSolicitacaoDominio(empresa.id, motivo);
228	      carregar();
229	    } catch (e) {
230	      alert(e.message);
231	    }
232	  };
233	
234	  const solicitacoesDominio = empresas.filter((e) => e.custom_domain_status === 'pendente');
235	
236	  return (
237	    <div className="min-h-screen bg-gray-50 dark:bg-zinc-900">
238	      <LocalModeBanner />
239	      <header className="bg-white dark:bg-zinc-800 border-b border-gray-200 dark:border-zinc-700 px-6 py-4 flex items-center justify-between">
240	        <div>
241	          <h1 className="text-xl font-bold text-gray-900 dark:text-zinc-100">Painel Dev-Admin</h1>
242	          <p className="text-sm text-gray-500 dark:text-zinc-400">Gestão de Empresas</p>
243	        </div>
244	        <AdminNav active="/admin/empresas" />
245	      </header>
246	
247	      <main className="p-6 max-w-6xl mx-auto">
248	        <div className="flex items-center justify-between mb-6">
249	          <h2 className="text-lg font-semibold text-gray-900 dark:text-zinc-100">
250	            Empresas <span className="text-gray-400 dark:text-zinc-500 font-normal text-sm">({empresas.length})</span>
251	            {solicitacoesDominio.length > 0 && (
252	              <span className="ml-2 inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-amber-100 dark:bg-amber-950/40 text-amber-700 dark:text-amber-400 align-middle">
253	                {solicitacoesDominio.length} solicitação(ões) de domínio pendente(s)
254	              </span>
255	            )}
256	          </h2>
257	          {!isLocalMode && (
258	            <button
259	              onClick={() => setModal('novo')}
260	              className="px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700"
261	            >
262	              + Nova Empresa
263	            </button>
264	          )}
265	        </div>
266	
267	        {solicitacoesDominio.length > 0 && (
268	          <div className="mb-6 bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-900 rounded-xl p-4">
269	            <h3 className="text-sm font-semibold text-amber-800 dark:text-amber-300 mb-3">Solicitações de domínio personalizado</h3>
