                            {e.custom_domain} (recusado)
                          </span>
                        ) : e.custom_domain ? (
                          <span className="text-xs text-gray-500 dark:text-zinc-400 font-mono">{e.custom_domain}</span>
                        ) : (
                          <span className="text-xs text-gray-400 dark:text-zinc-500">—</span>
