import { Module } from '@nestjs/common';
import { RestauranteController } from './restaurante.controller';
import { OnboardingController } from './onboarding.controller';
import { CatalogoController } from './catalogo.controller';
import { CozinhaPortalController } from './cozinha-portal.controller';
import { KdsPortalController } from './kds-portal.controller';
import { RestauranteService } from './restaurante.service';
import { CozinhaGuard } from '../auth/cozinha.guard';
import { AuthModule } from '../auth/auth.module';
import { SupabaseModule } from '../supabase/supabase.module';
import { CategoriasModule } from '../categorias/categorias.module';
import { ProdutosModule } from '../produtos/produtos.module';
import { PedidosModule } from '../pedidos/pedidos.module';
import { MotoboyModule } from '../motoboy/motoboy.module';
import { SalaoModule } from '../salao/salao.module';

@Module({
  imports: [AuthModule, SupabaseModule, CategoriasModule, ProdutosModule, PedidosModule, MotoboyModule, SalaoModule],
  controllers: [RestauranteController, OnboardingController, CatalogoController, CozinhaPortalController, KdsPortalController],
  providers: [RestauranteService, CozinhaGuard],
})
export class RestauranteModule {}

import { IsBoolean, IsInt, IsOptional, IsString, Matches, MaxLength } from 'class-validator';

export class UpdateConfigDto {
  @IsOptional()
  @IsString()
  @MaxLength(500)
  pagbank_platform_token?: string;

  @IsOptional()
  @IsString()
  @MaxLength(100)
  pagbank_platform_account_id?: string;

  @IsOptional()
  @IsBoolean()
  pagbank_sandbox?: boolean;

  @IsOptional()
  @IsString()
  @MaxLength(500)
  cloudflare_tunnel_token?: string;

  // Domínio: apenas letras, números, pontos e hífens
  @IsOptional()
  @IsString()
  @MaxLength(200)
  @Matches(/^[a-zA-Z0-9.-]*$/, { message: 'Domínio inválido — use apenas letras, números, pontos e hífens' })
  cloudflare_domain?: string;

  // Instalação individual: restringe o admin a 1 restaurante só (mono-estabelecimento)
  @IsOptional()
  @IsBoolean()
  modo_individual?: boolean;

  @IsOptional()
  @IsInt()
  modo_individual_restaurant_id?: number | null;
}

